namespace HelpingHands.Api.Data;

// Identifiers are generated by the API, not supplied by callers.
public sealed class Beneficiary
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Reference { get; set; } = "";
    public Guid? LinkedUserId { get; set; }
    public Guid CreatedByUserId { get; set; }
    public string DisplayName { get; set; } = "";
    public string? ContactDetails { get; set; }
    public bool IsFamily { get; set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

public sealed class AssistanceRequest
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Reference { get; set; } = "";
    public Guid BeneficiaryId { get; set; }
    public Guid SubmittedByUserId { get; set; }
    public string? Category { get; set; }
    public string? ServiceSubtype { get; set; }
    public string Description { get; set; } = "";
    public decimal? RequiredQuantity { get; set; }
    public string? Unit { get; set; }
    public string Status { get; set; } = "Submitted";
    public bool AuthorityConfirmed { get; set; }
    public bool SharingAgreed { get; set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
    public Guid Version { get; set; } = Guid.NewGuid();
}

public sealed class DecisionHistory
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid? RequestId { get; set; }
    public Guid? ReferralId { get; set; }
    public Guid ActorUserId { get; set; }
    public string Action { get; set; } = "";
    public string? Reason { get; set; }
    public DateTimeOffset OccurredAt { get; set; } = DateTimeOffset.UtcNow;
}
